{
  "name": "repo_fetch",
  "description": "Shallow-fetch a repo at a branch, tag or commit into repos/<PROJECT>/<repo> (for reading code, review, graph). Optionally build its code-review-graph.",
  "group": "bitbucket",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "project": {
        "type": "string",
        "description": "Project key"
      },
      "repo": {
        "type": "string",
        "description": "Repo slug"
      },
      "ref": {
        "type": "string",
        "description": "Branch, tag or sha (default branch if empty)"
      },
      "graph": {
        "type": "boolean",
        "default": false,
        "description": "Also build the code graph"
      }
    },
    "required": [
      "project",
      "repo"
    ]
  }
}
